CREATE OR REPLACE FUNCTION mission_factory_owner.c384_dual_save_v1(p_lineage uuid, p_expected_version bigint, p_document jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();h mission_factory_owner.c384_authoring_heads; prior mission_factory_owner.c384_authoring_requests;
doc jsonb;fp text;response jsonb;next_version bigint;
BEGIN
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_lineage IS NULL OR p_request IS NULL OR p_expected_version IS NULL OR p_expected_version<0
THEN RAISE EXCEPTION 'C384_NORMAL_AUTH_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
-- Nessun permit Source abilita il consumer incompleto.
IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C384_INTEGRATION_DISABLED' USING ERRCODE='42501';END IF;
doc:=mission_factory_owner.c384_validate_dual_draft_v3(p_document);
fp:=mission_factory_owner.sha(jsonb_build_object('schema_version','c384-dual-save/1','lineage_id',p_lineage,'expected_version',p_expected_version,'document',doc));
PERFORM pg_advisory_xact_lock(hashtextextended('c384-request:'||p_request::text,384));
SELECT * INTO prior FROM mission_factory_owner.c384_authoring_requests WHERE request_key=p_request;
IF FOUND THEN
IF prior.actor_user IS DISTINCT FROM u OR prior.fingerprint IS DISTINCT FROM fp OR prior.lineage_id IS DISTINCT FROM p_lineage
THEN RAISE EXCEPTION 'C384_REQUEST_CONFLICT' USING ERRCODE='22023';END IF;RETURN prior.result;
END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('c384-lineage:'||p_lineage::text,384));
SELECT * INTO h FROM mission_factory_owner.c384_authoring_heads WHERE id=p_lineage FOR UPDATE;
IF NOT FOUND THEN
IF p_expected_version<>0 THEN RAISE EXCEPTION 'C384_VERSION_STALE' USING ERRCODE='40001';END IF;
INSERT INTO mission_factory_owner.c384_authoring_heads(id,author_user,current_version) VALUES(p_lineage,u,0) RETURNING * INTO h;
END IF;
IF h.author_user IS DISTINCT FROM u THEN RAISE EXCEPTION 'C384_AUTHOR_OWNERSHIP' USING ERRCODE='42501';END IF;
IF h.current_version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'C384_VERSION_STALE' USING ERRCODE='40001';END IF;
next_version:=h.current_version+1;
INSERT INTO mission_factory_owner.c384_authoring_versions(lineage_id,version,author_user,document,document_sha256,mechanical_sha256,ai_variant_sha256,human_variant_sha256)
VALUES(p_lineage,next_version,u,doc,mission_factory_owner.sha(doc),
mission_factory_owner.sha(jsonb_build_object('quest',doc->'quest','npc_bindings',doc->'npc_bindings','budget_policy_id',doc->'budget_policy_id','catalog_version',doc->'catalog_version')),
mission_factory_owner.sha(doc#>'{variants,ai}'),mission_factory_owner.sha(doc#>'{variants,human}'));
UPDATE mission_factory_owner.c384_authoring_heads SET current_version=next_version WHERE id=p_lineage;
response:=jsonb_build_object('schema_version','quest-dual-authoring-version/1','lineage_id',p_lineage,'version',next_version,'document_sha256',mission_factory_owner.sha(doc),'request_key',p_request);
INSERT INTO mission_factory_owner.c384_authoring_requests(request_key,actor_user,fingerprint,lineage_id,version,result) VALUES(p_request,u,fp,p_lineage,next_version,response);
RETURN response;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c395_prepare_assert_v1(p_lineage uuid, p_version bigint, p_episode uuid, p_location uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;u uuid:=auth.uid();
BEGIN
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_lineage IS NULL OR p_version IS NULL OR p_episode IS NULL
OR p_location IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
THEN RAISE EXCEPTION 'C395_NORMAL_STAFF_HUMAN_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
IF public.master_v2_is_master(u) IS DISTINCT FROM true
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C395_HUMAN_PREPARE_DISABLED' USING ERRCODE='42501';END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
IF v.author_user IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
THEN RAISE EXCEPTION 'C395_HUMAN_VERSION_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
PERFORM mission_factory_owner.quest_operator_assert_v3(p_episode);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c395_start_assert_v1(p_prepare uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sid uuid;
BEGIN
SELECT session_id INTO STRICT sid FROM mission_factory_owner.quest_run_sources WHERE prepare_request_key=p_prepare;
PERFORM mission_factory_owner.c384_human_identity_v1(sid);
IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources WHERE session_id=sid AND start_request_key IS NOT NULL) THEN RETURN;END IF;
IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND start_enabled)
THEN RAISE EXCEPTION 'C395_MANUAL_OPENING_COMPOSITION_DISABLED' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_prepare_v1(p_arc uuid, p_episode uuid, p_location uuid, p_roster uuid[], p_lineage uuid, p_authoring_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_factory_owner.quest_arcs%rowtype;
e mission_factory_owner.quest_episodes%rowtype;
pub mission_factory_owner.publications%rowtype;
p public.mission_plans%rowtype;
v public.mission_plan_versions%rowtype;
d mission_generic_owner.definitions%rowtype;
q mission_factory_owner.quest_run_sources%rowtype;
sid uuid; fp text; release_sha text; receipt jsonb; binding_snapshot jsonb; previous_id uuid; previous_sha text;
begin

PERFORM mission_factory_owner.c395_prepare_assert_v1(p_lineage,p_authoring_version,p_episode,p_location);
PERFORM mission_factory_owner.c395_revision_issue_v1(p_lineage,p_authoring_version,p_arc,p_episode,p_request);
perform mission_factory_owner.quest_operator_assert_v3(p_episode);
if p_arc is null or p_episode is null or p_location is null or p_request is null
or p_roster is null or cardinality(p_roster) not between 1 and 4
then raise exception 'MF_QUEST_PREPARE_INPUT' using errcode='22023'; end if;
perform pg_advisory_xact_lock(hashtextextended(p_request::text,25092511));
fp:=mission_factory_owner.sha(jsonb_build_object('arc',p_arc,'episode',p_episode,
'location',p_location,'roster',to_jsonb(p_roster),'direction_mode','human','assigned_master',auth.uid(),'lineage_id',p_lineage,'authoring_version',p_authoring_version));
select * into q from mission_factory_owner.quest_run_sources
where prepare_request_key=p_request for share;
if found then
if q.prepare_fingerprint<>fp then
raise exception 'MF_QUEST_PREPARE_REQUEST_CONFLICT' using errcode='40001';
end if;
PERFORM mission_factory_owner.c384_human_identity_v1(q.session_id);
return jsonb_build_object('schema_version','quest-human-episode-prepare/1',
'request_key',p_request,'state','prepared','quest_arc_id',q.arc_id,
'quest_episode_id',q.episode_id,'native_session_id',q.session_id,
'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
'plan_sha256',q.plan_sha256,'roster_snapshot_sha256',q.roster_snapshot_sha256,
'staff_release_sha256',q.staff_release_sha256,'location_id',q.location_id,
'control_version',1,'opening_publication_id',null);
end if;
select * into strict a from mission_factory_owner.quest_arcs
where id=p_arc for update;
select * into strict e from mission_factory_owner.quest_episodes
where id=p_episode and arc_id=p_arc for update;
select * into strict pub from mission_factory_owner.publications
where request_key=a.publication_request for share;
perform 1 from public.locations where id=p_location and is_active and is_test=mission_factory_owner.quest_is_simulation_v4(a.id) and (mission_factory_owner.quest_is_simulation_v4(a.id) or not coalesce(is_exam_room,false)) for update;
if not found then raise exception 'MF_QUEST_PREPARE_LOCATION' using errcode='42501'; end if;
release_sha:=case when a.availability_scope='staff' then mission_factory_owner.staff_release_sha_v1() else a.public_release_sha256 end;
if e.ordinal>1 then
if a.quest_kind<>'trama' then raise exception 'MF_QUEST_ONE_SHOT_HAS_NO_SUCCESSOR';end if;
select tr.id,tr.continuity_private_sha256 into strict previous_id,previous_sha
from mission_factory_owner.quest_episodes pe
join mission_factory_owner.quest_run_sources pq on pq.episode_id=pe.id and pq.state='terminal'
join mission_factory_owner.quest_terminal_receipts tr on tr.id=pq.terminal_receipt_id and tr.episode_id=pe.id
join public.mission_run_publications pp on pp.id=tr.publication_id and pp.status='committed'
join public.mission_run_outbox po on po.publication_id=pp.id and po.state='published'
where pe.arc_id=a.id and pe.ordinal=e.ordinal-1 and pe.state in('completed','failed')
and tr.continuity_private_sha256=mission_factory_owner.sha(tr.continuity_private)
and tr.continuity_public_sha256=mission_factory_owner.sha(tr.continuity_public)
for share of pe,pq,tr,pp,po;
end if;
if e.state<>'source_only'
or (e.ordinal=1 and a.state not in('staff_source','public_source')) or (e.ordinal>1 and a.state<>'in_progress')
or a.source_sha256<>mission_factory_owner.sha(a.source_document)
or e.source_sha256<>mission_factory_owner.sha(e.source_document)
or pub.content_kind<>'quest_human' or not mission_factory_owner.quest_public_open_v3(a.id)
or pub.quest_arc_id<>a.id or pub.release_revision_sha256<>release_sha
or p_roster is distinct from e.member_character_ids
or exists(select 1 from mission_factory_owner.quest_run_sources where episode_id=e.id)
then raise exception 'MF_QUEST_PREPARE_SOURCE_STALE' using errcode='55000'; end if;
select * into strict p from public.mission_plans
where source_kind='quest' and quest_episode_id=e.id and stato='attivo' for share;
select * into strict v from public.mission_plan_versions
where plan_id=p.id and stato='approvata' order by versione desc limit 1 for share;
select * into strict d from mission_generic_owner.definitions
where plan_version_id=v.id and plan_sha256=v.plan_sha256
and definition->>'schema_version'='mission-factory-quest-definition/1'
and definition->>'quest_episode_id'=e.id::text
and definition->>'source_sha256'=e.source_sha256
order by version desc limit 1 for share;
if p.quest_source_sha256<>e.source_sha256 or v.plan_sha256 is null
or d.definition_sha256<>mission_internal.fingerprint(d.definition)
or not exists(select 1 from public.mission_plan_steps
where plan_version_id=v.id and step_key=v.initial_step_key)
then raise exception 'MF_QUEST_PREPARE_PLAN_STALE' using errcode='55000'; end if;
if mission_factory_owner.quest_compile_check_v1(e.id) is distinct from '[]'::jsonb then raise exception 'MF_QUEST_PREPARE_CAPABILITY_UNQUALIFIED' using errcode='55000';end if;
perform mission_factory_owner.quest_roster_scope_assert_v3(a.id,p_location,p_roster);
if exists(select 1 from unnest(p_roster) x where
exists(select 1 from mission_ai_board_owner.roster_reservations rr
where rr.character_id=x and rr.state='active')
or exists(select 1 from public.master_v2_participants mp
join public.master_v2_sessions ms on ms.id=mp.session_id
where mp.character_id=x and mp.left_at is null and ms.closed_at is null))
then raise exception 'MF_QUEST_PREPARE_ROSTER_BUSY' using errcode='40001'; end if;
if exists(select 1 from public.master_v2_sessions
where location_id=p_location and closed_at is null)
then raise exception 'MF_QUEST_PREPARE_ROOM_BUSY' using errcode='40001'; end if;
sid:=extensions.uuid_generate_v5(p_request,'mission-factory:quest-session/1');
insert into public.master_v2_sessions
(id,location_id,tipo,stato,master_user,owner_kind,control_version,
mission_id,titolo,quest_kind)
values(sid,p_location,'quest','preparazione',auth.uid(),'human',1,
null,left(coalesce(nullif(e.source_document->>'title',''),'Quest Human'),120),a.quest_kind);
INSERT INTO mission_factory_owner.c395_prepared_sources(session_id,revision_id,assigned_master,prepare_request)
SELECT sid,id,auth.uid(),p_request FROM mission_factory_owner.c395_quest_revisions WHERE episode_id=e.id AND lineage_id=p_lineage AND authoring_version=p_authoring_version;
insert into mission_factory_owner.quest_run_sources
(session_id,arc_id,episode_id,source_sha256,plan_id,plan_version_id,
plan_sha256,definition_id,definition_sha256,roster_character_ids,roster_snapshot_sha256,
staff_release_sha256,location_id,prepare_request_key,prepare_fingerprint,episode_ordinal,previous_episode_terminal_receipt_id,continuity_sha256)
values(sid,a.id,e.id,e.source_sha256,p.id,v.id,v.plan_sha256,
d.id,d.definition_sha256,p_roster,
mission_factory_owner.sha(to_jsonb(p_roster)),release_sha,p_location,p_request,fp,e.ordinal,previous_id,previous_sha)
returning * into q;
binding_snapshot:=mission_factory_owner.c395_binding_projection_v1(q);
insert into mission_generic_owner.run_bindings
(master_session_id,definition_id,snapshot,snapshot_sha256)
values(sid,d.id,binding_snapshot,mission_internal.fingerprint(binding_snapshot));
insert into public.master_v2_participants
(session_id,character_id,user_id_snapshot,engagement_state)
select sid,c.id,c.user_id,'attivo' from unnest(p_roster) with ordinality x(id,ord)
join public.characters c on c.id=x.id order by x.ord;
PERFORM mission_factory_owner.c384_human_bind_seal_v1(sid,p_lineage,p_authoring_version,e.id,d.id,p_request);
insert into public.mission_run_state
(master_session_id,mission_id,source_kind,quest_arc_id,quest_episode_id,
plan_id,plan_version_id,plan_version,plan_sha256,current_step_key,
run_phase,control_version)
values(sid,null,'quest',a.id,e.id,p.id,v.id,v.versione,v.plan_sha256,
v.initial_step_key,'preparazione',1);
PERFORM mission_factory_owner.c395_source_assert_v1(sid);
receipt:=jsonb_build_object('schema_version','quest-human-episode-prepare/1',
'request_key',p_request,'state','prepared','quest_arc_id',a.id,
'quest_episode_id',e.id,'native_session_id',sid,
'source_sha256',e.source_sha256,'plan_version_id',v.id,
'plan_sha256',v.plan_sha256,
'roster_snapshot_sha256',mission_factory_owner.sha(to_jsonb(p_roster)),
'staff_release_sha256',release_sha,'location_id',p_location,
'control_version',1,'opening_publication_id',null);
return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_start_v1(p_prepare_request uuid, p_expected_control_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ep mission_factory_owner.quest_episodes; q mission_factory_owner.quest_run_sources%rowtype;
a mission_factory_owner.quest_arcs%rowtype;
m public.master_v2_sessions%rowtype;
r public.mission_run_state%rowtype;
e public.mission_run_events%rowtype;
eid uuid; fp text; ctx text; receipt jsonb;
locked_session uuid; locked_location uuid;
begin
PERFORM mission_factory_owner.c395_start_assert_v1(p_prepare_request);
perform mission_factory_owner.quest_operator_assert_v3((select episode_id from mission_factory_owner.quest_run_sources where prepare_request_key=p_prepare_request));
if p_prepare_request is null or p_request is null
or p_request=p_prepare_request
or p_expected_control_version is null or p_expected_control_version<1
then raise exception 'MF_QUEST_START_INPUT' using errcode='22023'; end if;
perform pg_advisory_xact_lock(hashtextextended(p_request::text,25092602));
select session_id,location_id into strict locked_session,locked_location
from mission_factory_owner.quest_run_sources
where prepare_request_key=p_prepare_request;
perform 1 from public.locations where id=locked_location for update;
if not found then raise exception 'MF_QUEST_START_LOCATION' using errcode='40001'; end if;
perform public.master_v2_lock_scope(locked_session);
select * into strict m from public.master_v2_sessions
where id=locked_session for update;
select * into strict q from mission_factory_owner.quest_run_sources
where prepare_request_key=p_prepare_request for update;
if q.session_id is distinct from locked_session
or q.location_id is distinct from locked_location
or m.location_id is distinct from locked_location
then raise exception 'MF_QUEST_START_SCOPE_DRIFT' using errcode='40001'; end if;
select * into strict a from mission_factory_owner.quest_arcs
where id=q.arc_id for share;
select * into strict r from public.mission_run_state
where master_session_id=q.session_id for update;
fp:=mission_internal.fingerprint(jsonb_build_object(
'schema_version','quest-human-episode-start-request/1',
'prepare_request_key',p_prepare_request,'request_key',p_request,
'expected_control_version',p_expected_control_version,
'session_id',q.session_id,'episode_id',q.episode_id,
'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
'roster_snapshot_sha256',q.roster_snapshot_sha256));
if q.start_request_key is not null then
if q.start_request_key is distinct from p_request
then raise exception 'MF_QUEST_ALREADY_STARTED' using errcode='40001'; end if;
select * into strict e from public.mission_run_events
where id=q.start_event_id and master_session_id=q.session_id for share;
if e.operation_kind<>'bind' or e.status<>'committed'
or e.request_fingerprint<>fp
or e.request_key_sha256<>mission_internal.request_key_sha256(p_request)
then raise exception 'MF_QUEST_START_REPLAY_DRIFT' using errcode='40001'; end if;
return e.result;
end if;
if q.state<>'prepared' or q.control_version<>p_expected_control_version
or r.control_version<>1 or r.run_phase<>'preparazione'
or r.last_event_id is not null or r.source_kind<>'quest'
or r.quest_episode_id is distinct from q.episode_id
or m.stato<>'preparazione' or m.control_version<>1
or m.closed_at is not null or m.location_id<>q.location_id
or (q.availability_scope='staff' and q.staff_release_sha256<>mission_factory_owner.staff_release_sha_v1())
then raise exception 'MF_QUEST_START_CAS' using errcode='40001'; end if;
perform mission_factory_owner.c395_source_assert_v1(q.session_id);
perform mission_factory_owner.quest_roster_scope_assert_v3(q.arc_id,q.location_id,q.roster_character_ids);
select * into strict ep from mission_factory_owner.quest_episodes where id=q.episode_id for share;
perform mission_factory_owner.quest_enrollment_assert_v1(
q.episode_id,q.source_sha256,ep.roster_assignment_id,
q.roster_character_ids,q.location_id,true,q.session_id);
if exists(select 1 from public.master_v2_participants mp
join public.master_v2_sessions ms on ms.id=mp.session_id
where mp.character_id=any(q.roster_character_ids) and mp.left_at is null
and ms.closed_at is null and ms.id<>q.session_id)
or exists(select 1 from mission_ai_board_owner.roster_reservations rr
where rr.character_id=any(q.roster_character_ids) and rr.state='active')
then raise exception 'MF_QUEST_ROSTER_BUSY' using errcode='40001'; end if;
eid:=extensions.uuid_generate_v5(p_request,'mission-factory:quest-start-event/1');
ctx:=mission_internal.fingerprint(jsonb_build_object(
'schema_version','mission-context/1.0',
'master_session_id',q.session_id::text,'event_id',eid::text,
'plan_id',q.plan_id::text,'plan_version_id',q.plan_version_id::text,
'step_key',r.current_step_key,'event_version_after',1));
receipt:=jsonb_build_object('schema_version','quest-human-episode-start/1',
'request_key',p_request,'prepare_request_key',p_prepare_request,
'state','opening_pending','native_session_id',q.session_id,
'start_event_id',eid,'opening_publication_id',null,
'run_control_version',1,'provider_attempt_state','not_authorized');
update mission_factory_owner.quest_run_sources
set state='opening_pending',control_version=control_version+1,
start_request_key=p_request,start_event_id=eid
where session_id=q.session_id and state='prepared'
and control_version=p_expected_control_version;
if not found then raise exception 'MF_QUEST_START_CAS' using errcode='40001'; end if;
insert into public.mission_run_events(
id,master_session_id,operation_kind,request_key_sha256,request_fingerprint,
status,plan_version_id,step_after,version_after,context_fingerprint,result)
values(eid,q.session_id,'bind',mission_internal.request_key_sha256(p_request),
fp,'committed',q.plan_version_id,r.current_step_key,1,ctx,receipt);
update public.mission_run_state
set last_event_id=eid,updated_at=clock_timestamp()
where master_session_id=q.session_id and last_event_id is null;
if not found then raise exception 'MF_QUEST_START_RUN_DRIFT' using errcode='40001'; end if;
insert into public.mission_run_outbox(
event_id,master_session_id,surface_kind,event_version_after,
step_key,context_fingerprint)
values(eid,q.session_id,'mission_narrative',1,r.current_step_key,ctx);
-- Human opening event is routed by the same Native outbox trigger.
-- No AI capability, work item, lifecycle worker or provider authorization is created.
PERFORM 1 FROM public.mission_run_outbox WHERE event_id=eid AND state='human_directed';
IF NOT FOUND THEN RAISE EXCEPTION 'C395_HUMAN_OPENING_ROUTE_REQUIRED';END IF;
return receipt;
end; $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_dual_get_v3(p_lineage uuid, p_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;
BEGIN
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'C412_NORMAL_AUTHOR_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(auth.uid());
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version AND author_user=auth.uid();
IF v.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(v.document) THEN RAISE EXCEPTION 'C412_IMMUTABLE_AUTHORING_DRIFT';END IF;
RETURN jsonb_build_object('schema_version','quest-dual-authoring-version/1','lineage_id',v.lineage_id,'version',v.version,'document_sha256',v.document_sha256,'document',v.document);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c416_arc_assert_v1(p_arc uuid, p_live boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a mission_factory_owner.quest_arcs;p mission_factory_owner.publications;
BEGIN
SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=p_arc;
SELECT * INTO STRICT p FROM mission_factory_owner.publications WHERE request_key=a.publication_request;
PERFORM mission_factory_owner.c416_draft_assert_v1(a.draft_id,p_live);
IF a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR p.content_kind IS DISTINCT FROM 'quest_human' OR p.quest_arc_id IS DISTINCT FROM a.id OR p.source_sha256 IS DISTINCT FROM a.source_sha256 OR a.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(a.source_document) OR a.availability_scope IS DISTINCT FROM 'staff' OR a.execution_context IS DISTINCT FROM 'staff_simulation' OR p.target IS DISTINCT FROM 'staff' OR p.state IS DISTINCT FROM 'staff' THEN RAISE EXCEPTION 'C416_HUMAN_NATIVE_PUBLICATION_REQUIRED';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_dual_create_v3(p_lineage uuid, p_expected_version bigint, p_document jsonb, p_roster uuid[], p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h mission_factory_owner.c416_human_draft_sources;k mission_factory_owner.c416_kind_admission;v mission_factory_owner.c384_authoring_versions;doc jsonb;result jsonb;fp text;save_result jsonb;draft_id uuid;roster_id uuid;users uuid[];
BEGIN
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.master_v2_is_master(auth.uid()) IS DISTINCT FROM true OR p_lineage IS NULL OR p_request IS NULL OR p_expected_version IS NULL OR p_expected_version<0 OR p_roster IS NULL OR cardinality(p_roster) NOT BETWEEN 1 AND 4 OR array_position(p_roster,NULL) IS NOT NULL OR (SELECT count(DISTINCT x) FROM unnest(p_roster)x)<>cardinality(p_roster) THEN RAISE EXCEPTION 'C416_NORMAL_MASTER_ROSTER_INPUT';END IF;
PERFORM mission_factory_owner.assert_editor(auth.uid());
fp:=mission_factory_owner.sha(jsonb_build_object('lineage',p_lineage,'expected_version',p_expected_version,'document',p_document,'roster',p_roster,'actor',auth.uid()));
PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,416));
SELECT * INTO h FROM mission_factory_owner.c416_human_draft_sources WHERE request_key=p_request;
IF FOUND THEN IF h.author_user IS DISTINCT FROM auth.uid() OR h.fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'C416_CREATE_REPLAY_CONFLICT';END IF;PERFORM mission_factory_owner.c416_draft_assert_v1(h.draft_id,false);RETURN h.result;END IF;
PERFORM mission_factory_owner.manual_authoring_assert_v1('create',NULL);
SELECT * INTO STRICT k FROM mission_factory_owner.c416_kind_admission WHERE singleton;
IF mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true OR NOT auth.uid()=ANY(k.allowed_auth_ids) THEN RAISE EXCEPTION 'C416_KIND_AUTHORING_DISABLED';END IF;
SELECT array_agg(c.user_id ORDER BY x.ord) INTO users FROM unnest(p_roster) WITH ORDINALITY x(id,ord) JOIN public.characters c ON c.id=x.id JOIN public.profiles pr ON pr.id=c.user_id;
IF cardinality(users) IS DISTINCT FROM cardinality(p_roster) OR NOT users<@k.allowed_auth_ids OR combat_consumer_private.staff_test_allowed('0b85f354-9cdb-47e1-baf9-3d266bb7e06b',array_append(users,auth.uid()),false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'C416_NATIVE_PROTECTED_ROSTER_REQUIRED';END IF;
draft_id:=extensions.uuid_generate_v5(p_request,'quest-human-draft/3');roster_id:=extensions.uuid_generate_v5(p_request,'quest-human-roster/3');
IF p_document#>'{quest,roster_assignment_id}' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'C416_ROSTER_SERVER_ISSUED_ONLY';END IF;
doc:=jsonb_set(p_document,'{quest,roster_assignment_id}',to_jsonb(roster_id::text));
save_result:=mission_factory_owner.c384_dual_save_v1(p_lineage,p_expected_version,doc,p_request);
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=(save_result->>'version')::bigint;
doc:=jsonb_set(v.document,'{content_kind}','"quest_human"'::jsonb);
INSERT INTO mission_factory_owner.drafts(id,author_user,document,document_sha256,catalog_version,control_version) VALUES(draft_id,auth.uid(),doc,mission_factory_owner.sha(doc),doc->>'catalog_version',v.version);
INSERT INTO mission_factory_owner.quest_roster_assignments(id,draft_id,roster_version,member_character_ids,assigned_by) VALUES(roster_id,draft_id,1,p_roster,auth.uid());
result:=jsonb_build_object('schema_version','quest-dual-human-create/3','request_key',p_request,'lineage_id',p_lineage,'version',v.version,'draft_id',draft_id,'roster_assignment_id',roster_id,'source_sha256',v.document_sha256,'human_document_sha256',mission_factory_owner.sha(doc),'catalog_sha256',k.catalog_sha256);
INSERT INTO mission_factory_owner.c416_human_draft_sources VALUES(draft_id,p_lineage,v.version,auth.uid(),p_request,fp,v.document_sha256,mission_factory_owner.sha(doc),v.mechanical_sha256,k.catalog_version,k.catalog_sha256,k.request_key,roster_id,p_roster,result);
PERFORM mission_factory_owner.c416_draft_assert_v1(draft_id,true);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_preview_v3(p_draft uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d mission_factory_owner.drafts;
        doc jsonb; variant jsonb; roster mission_factory_owner.quest_roster_assignments;
        errors jsonb:='[]'::jsonb; validated jsonb:='[]'::jsonb;
        episode_count integer; kind text; review_status text; ep jsonb; ord bigint;
        reward_text text; checked_policy jsonb; basis jsonb; seal text;
begin
PERFORM mission_factory_owner.c416_draft_assert_v1(p_draft,true);
  if p_draft is null or p_expected_version is null then
    raise exception 'MF_QUEST_PREVIEW_INPUT' using errcode='22023'; end if;
  select * into d from mission_factory_owner.drafts where id=p_draft;
  if not found then raise exception 'MF_DRAFT_NOT_FOUND' using errcode='P0002'; end if;

  perform mission_factory_owner.manual_authoring_assert_v1('preview',null);
  perform mission_factory_owner.assert_editor(d.author_user);
  if d.control_version<>p_expected_version or d.state not in('draft','previewed')
    then raise exception 'MF_DRAFT_DRIFT' using errcode='40001'; end if;
  if d.document->>'schema_version' is distinct from 'mission-factory-draft/3' then
    return mission_factory_owner.preview_eval(p_draft,p_expected_version,auth.uid(),false);
  end if;
  kind:=d.document->>'content_kind';
  if kind is distinct from 'quest_human' then
    raise exception 'MF_PREVIEW_V2_KIND_UNQUALIFIED' using errcode='55000'; end if;
  doc:=mission_factory_owner.validate_quest_draft_v2(d.document);
  if d.document_sha256 is distinct from mission_factory_owner.sha(doc)
     or d.catalog_version is distinct from doc->>'catalog_version'
  then raise exception 'MF_QUEST_PREVIEW_SOURCE_DRIFT' using errcode='40001'; end if;
  episode_count:=jsonb_array_length(doc#>'{quest,episodes}');
  if (doc#>>'{quest,quest_kind}'='one_shot' and episode_count<>1)
     or (doc#>>'{quest,quest_kind}'='trama' and episode_count<2)
  then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','MF_QUEST_EPISODES_REQUIRED','path','quest.episodes')); end if;
  if not mission_factory_owner.c416_kind_live_v1()
  then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','MF_QUEST_CATALOG_UNQUALIFIED','path','catalog_version')); end if;
  select * into roster from mission_factory_owner.quest_roster_assignments
    where draft_id=d.id and active;
  if roster.id is null or doc#>>'{quest,roster_assignment_id}' is distinct from roster.id::text
  then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','MF_QUEST_ROSTER_REQUIRED','path','quest.roster_assignment_id')); end if;
  variant:=doc#>'{variants,human}';
  if variant->>'state' is distinct from 'complete'
     or jsonb_typeof(variant->'document') is distinct from 'object'
  then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','MF_QUEST_VARIANT_REQUIRED','path','variants.human'));
  else
    begin
      perform mission_factory_owner.c384_validate_variant_v2(doc,variant->'document','human');
      validated:=jsonb_build_array('human');
    exception when others then
      errors:=errors||jsonb_build_array(jsonb_build_object(
        'code','MF_QUEST_VARIANT_INVALID','path','variants.human'));
    end;
  end if;
  if mission_factory_owner.c416_kind_live_v1() then
    errors:=errors||mission_factory_owner.quest_deep_validate_v2(d.id,doc);
  end if;
  if d.sensitive_review_required then
    select r.status into review_status from mission_factory_owner.sensitive_reviews r
      where r.draft_id=d.id and r.document_sha256=d.document_sha256
      order by r.requested_at desc,r.request_key desc limit 1;
    if review_status is distinct from 'approved' then
      errors:=errors||jsonb_build_array(jsonb_build_object(
        'code','MF_QUEST_SENSITIVE_REVIEW_REQUIRED','path','sensitive_review'));
    end if;
  end if;
  if doc->>'budget_policy_id' is null then
    errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','MF_QUEST_BUDGET_POLICY_REQUIRED','path','budget_policy_id'));
  end if;
  for ep,ord in select value,ordinality from jsonb_array_elements(doc#>'{quest,episodes}')
    with ordinality x(value,ordinality) loop
    if ord<episode_count and ep#>>'{terminal_rules,reward_policy_id}' is not null then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_REWARD_ONLY_FINAL_EPISODE','path','quest.episodes'));
    end if;
  end loop;
  reward_text:=doc#>>array['quest','episodes',(episode_count-1)::text,'terminal_rules','reward_policy_id'];
  if coalesce(reward_text,'') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_REWARD_POLICY_REQUIRED','path','quest.episodes'));
  else
    begin
      checked_policy:=mission_factory_owner.quest_reward_policy_checked_v2(reward_text::uuid);
    exception when SQLSTATE '55000' or SQLSTATE '22023' then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_REWARD_POLICY_UNQUALIFIED','path','quest.episodes'));
    end;
  end if;
  if errors='[]'::jsonb then
    begin
      basis:=mission_factory_owner.c416_preview_basis_v3(d.id,d.control_version,false);
      if basis->>'reward_policy_sha256' is distinct from checked_policy->>'policy_sha256' then
        raise exception 'MF_QUEST_REWARD_POLICY_DRIFT' using errcode='40001';end if;
      seal:=mission_factory_owner.sha(basis);
    exception when SQLSTATE '55000' or SQLSTATE '22023' or no_data_found then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_DEPENDENCIES_UNQUALIFIED','path','quest'));
      seal:=null;
    end;
  end if;
  return jsonb_build_object('schema_version','quest-human-preview/3',
    'draft_id',d.id,'draft_version',d.control_version,
    'content_kind','quest_human','quest_kind',doc#>>'{quest,quest_kind}',
    'preview_seal',seal,'validation_mode','human_only',
    'required_variants',jsonb_build_array('human'),'validated_variants',validated,
    'errors',errors);
end $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_publish_v3(p_draft uuid, p_expected_version bigint, p_preview_seal text, p_request uuid, p_visibility text, p_scheduled_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<publisher>>
declare d mission_factory_owner.drafts; prior mission_factory_owner.publications;
        roster mission_factory_owner.quest_roster_assignments; doc jsonb; ep jsonb;
        locked_basis jsonb; preview jsonb; policy jsonb; fp text; source_sha text; policy_text text; release_sha text;
        policy_id uuid; arc_id uuid; episode_id uuid; first_episode_id uuid;
        episode_count integer; ord bigint; receipt jsonb; delivery jsonb; execution text; ad mission_factory_owner.quest_fixed30_admission;
begin
  if auth.uid() is null or p_draft is null or p_request is null
     or p_expected_version is null or coalesce(p_preview_seal,'') !~ '^[0-9a-f]{64}$'
  then raise exception 'MF_QUEST_PUBLISH_INPUT' using errcode='22023'; end if;
  if p_visibility IS DISTINCT FROM 'open' or (p_visibility='scheduled' and (p_scheduled_at is null or p_scheduled_at<=statement_timestamp())) or (p_visibility='open' and p_scheduled_at is not null) then raise exception 'MF_QUEST_PUBLIC_PUBLISH_INPUT' using errcode='22023';end if;
  fp:=mission_factory_owner.sha(jsonb_build_object('kind','quest_human','draft_id',p_draft,
    'expected_version',p_expected_version,'preview_seal',p_preview_seal,
    'visibility',p_visibility,'scheduled_at',p_scheduled_at));
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,25092028));
  select * into prior from mission_factory_owner.publications where request_key=p_request;
  if found then
    if prior.actor_user<>auth.uid() or prior.content_kind<>'quest_human' or prior.fingerprint<>fp
    then raise exception 'MF_QUEST_PUBLISH_REQUEST_CONFLICT' using errcode='40001'; end if;
    if prior.state not in('staff','open','scheduled') or prior.receipt is null then
      raise exception 'MF_QUEST_PUBLISH_REQUEST_PENDING' using errcode='40001'; end if;
    return prior.receipt;
  end if;
  perform mission_factory_owner.assert_editor(auth.uid());

  select * into d from mission_factory_owner.drafts where id=p_draft for update;
  if not found then raise exception 'MF_DRAFT_NOT_FOUND' using errcode='P0002'; end if;
  perform mission_factory_owner.assert_editor(d.author_user);
  PERFORM mission_factory_owner.c416_draft_assert_v1(p_draft,true);PERFORM mission_factory_owner.manual_authoring_assert_v1('publish',NULL);
 execution:='staff_simulation';
 select * into strict ad from mission_factory_owner.quest_fixed30_admission where singleton for share;
 release_sha:=mission_factory_owner.staff_release_sha_v1();
  if d.control_version<>p_expected_version or d.state not in('draft','previewed')
     or d.document->>'schema_version' is distinct from 'mission-factory-draft/3'
     or d.document->>'content_kind' is distinct from 'quest_human'
     or exists(select 1 from mission_factory_owner.publications
       where draft_id=p_draft and operation_kind='direct')
  then raise exception 'MF_QUEST_PUBLISH_DRAFT_DRIFT' using errcode='40001'; end if;
  doc:=mission_factory_owner.validate_quest_draft_v2(d.document);
  source_sha:=mission_factory_owner.sha(doc);
  if d.document_sha256<>source_sha or d.catalog_version<>doc->>'catalog_version'
  then raise exception 'MF_QUEST_PUBLISH_SOURCE_DRIFT' using errcode='40001'; end if;
  locked_basis:=mission_factory_owner.c416_preview_basis_v3(p_draft,p_expected_version,true);
  if mission_factory_owner.sha(locked_basis) is distinct from p_preview_seal then
    raise exception 'MF_QUEST_PUBLISH_DEPENDENCY_DRIFT' using errcode='40001';end if;
  preview:=public.mission_factory_quest_human_preview_v3(p_draft,p_expected_version);
  if preview->>'schema_version' is distinct from 'quest-human-preview/3'
     or preview->'errors'<>'[]'::jsonb
     or preview->>'preview_seal' is distinct from p_preview_seal
  then raise exception 'MF_QUEST_PUBLISH_PREVIEW_DRIFT' using errcode='40001'; end if;
  select * into roster from mission_factory_owner.quest_roster_assignments
    where id=(doc#>>'{quest,roster_assignment_id}')::uuid
      and draft_id=p_draft and active for share;
  if roster.id is null then raise exception 'MF_QUEST_PUBLISH_ROSTER' using errcode='55000'; end if;
  episode_count:=jsonb_array_length(doc#>'{quest,episodes}');
  for ep,ord in select value,ordinality from jsonb_array_elements(doc#>'{quest,episodes}')
    with ordinality x(value,ordinality) loop
    policy_text:=ep#>>'{terminal_rules,reward_policy_id}';
    if ord<episode_count and policy_text is not null then
      raise exception 'MF_QUEST_REWARD_ONLY_FINAL_EPISODE' using errcode='22023'; end if;
  end loop;
  policy_text:=doc#>>array['quest','episodes',(episode_count-1)::text,'terminal_rules','reward_policy_id'];
  if coalesce(policy_text,'') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then raise exception 'MF_QUEST_REWARD_POLICY_REQUIRED' using errcode='22023'; end if;
  policy_id:=policy_text::uuid;
  policy:=mission_factory_owner.quest_reward_policy_checked_v2(policy_id);
  IF EXISTS(SELECT 1 FROM unnest(roster.member_character_ids)x(id) JOIN public.characters c ON c.id=x.id WHERE NOT(c.user_id=ANY((SELECT allowed_auth_ids FROM mission_factory_owner.c416_kind_admission WHERE singleton)))) THEN RAISE EXCEPTION 'C416_NORMAL_NATIVE_STAFF_ROSTER';END IF;
  if policy->>'policy_sha256' is distinct from locked_basis->>'reward_policy_sha256'
     or release_sha is distinct from locked_basis->>'release_sha256' then
    raise exception 'MF_QUEST_PUBLISH_POLICY_DRIFT' using errcode='40001';end if;
  arc_id:=extensions.uuid_generate_v5(p_request,'mission-factory:quest-arc/2');
  insert into mission_factory_owner.publications(
    request_key,operation_kind,draft_id,draft_version,actor_user,fingerprint,preview_seal,
    visibility,target,due_at,state,transaction_id,backend_pid,content_kind,release_revision_sha256)
  values(p_request,'direct',p_draft,p_expected_version,auth.uid(),fp,p_preview_seal,
    case when execution='staff_simulation' and p_visibility='open' then 'staff' else p_visibility end,case when execution='staff_simulation' then 'staff' else 'public' end,p_scheduled_at,'preparing',txid_current(),pg_backend_pid(),'quest_human',release_sha);
  insert into mission_factory_owner.quest_arcs(
    id,publication_request,draft_id,draft_version,source_document,source_sha256,quest_kind,
    reward_policy_id,reward_policy_sha256,roster_assignment_id,member_character_ids,created_by,availability_scope,public_release_sha256,state,execution_context,execution_qualification_sha256,execution_auth_ids,logical_visibility,logical_due_at)
  values(arc_id,p_request,p_draft,p_expected_version,doc,source_sha,doc#>>'{quest,quest_kind}',
    policy_id,policy->>'policy_sha256',roster.id,roster.member_character_ids,auth.uid(),'staff',release_sha,'staff_source',execution,(SELECT review_sha256 FROM mission_factory_owner.c416_kind_admission WHERE singleton),(SELECT allowed_auth_ids FROM mission_factory_owner.c416_kind_admission WHERE singleton),p_visibility,p_scheduled_at);
  for ep,ord in select value,ordinality from jsonb_array_elements(doc#>'{quest,episodes}')
    with ordinality x(value,ordinality) loop
    episode_id:=extensions.uuid_generate_v5(arc_id,'mission-factory:quest-episode/2:'||ord::text);
    insert into mission_factory_owner.quest_episodes(
      id,arc_id,ordinal,episode_key,source_document,source_sha256,roster_assignment_id,member_character_ids)
    values(episode_id,arc_id,ord::integer,ep->>'episode_key',ep,mission_factory_owner.sha(ep),roster.id,roster.member_character_ids);
    if ord=1 then first_episode_id:=episode_id; end if;
  end loop;
  receipt:=jsonb_build_object('schema_version','quest-human-publish-receipt/3',
    'request_key',p_request,'draft_id',p_draft,'content_kind','quest_human',
    'quest_kind',doc#>>'{quest,quest_kind}','state',case when execution='staff_simulation' and p_visibility='open' then 'staff' else p_visibility end,'visibility',case when execution='staff_simulation' and p_visibility='open' then 'staff' else p_visibility end,
    'scheduled_at',p_scheduled_at,'mission_id',null,'quest_arc_id',arc_id,
    'quest_episode_id',first_episode_id,'source_sha256',source_sha,
    'config_version',null,'activation_id',null);
  delivery:=jsonb_build_object('schema_version','quest-human-delivery/3',
    'content_kind','quest_human','state',case when execution='staff_simulation' and p_visibility='open' then 'staff' else p_visibility end,'mission_id',null,'quest_arc_id',arc_id,
    'quest_episode_id',first_episode_id,'opened_at',case when p_visibility='open' and execution='public_real' then clock_timestamp() else null end,
    'reason_code',case when p_visibility='scheduled' then 'MF_QUEST_SCHEDULE_PENDING' when execution='staff_simulation' then 'MF_QUEST_PUBLIC_STAFF_RESERVED' else null end);
  update mission_factory_owner.publications set state=case when execution='staff_simulation' and p_visibility='open' then 'staff' else p_visibility end,quest_arc_id=arc_id,
    quest_episode_id=first_episode_id,source_sha256=source_sha,receipt=publisher.receipt,
    delivery=publisher.delivery,updated_at=clock_timestamp()
    where request_key=p_request and state='preparing' and transaction_id=txid_current()
      and backend_pid=pg_backend_pid();
  if not found then raise exception 'MF_QUEST_PUBLISH_FINALIZE_LOST' using errcode='40001'; end if;
  update mission_factory_owner.drafts set state='published',publish_request=p_request,
    updated_at=clock_timestamp() where id=p_draft and control_version=p_expected_version;
  if not found then raise exception 'MF_QUEST_DRAFT_FINALIZE_LOST' using errcode='40001'; end if;
  for episode_id in select id from mission_factory_owner.quest_episodes where quest_episodes.arc_id=publisher.arc_id order by ordinal loop
    perform mission_factory_owner.quest_compile_v1(episode_id);
  end loop;
  return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_runtime_state_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources;m public.master_v2_sessions;r public.mission_run_state;ev public.mission_run_events;hw mission_generic_owner.regia_human_windows_v1;scene jsonb;scope jsonb;ctx jsonb;term jsonb;ds jsonb:='[]'::jsonb;reason text;active boolean;pending boolean;enc boolean;options jsonb:='[]'::jsonb;ascope jsonb;ne mission_factory_owner.quest_episodes;nextdto jsonb;
BEGIN
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR SHARE;SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session FOR SHARE;
 SELECT * INTO ev FROM public.mission_run_events WHERE id=r.last_event_id AND master_session_id=p_session FOR SHARE;
 SELECT * INTO hw FROM mission_generic_owner.regia_human_windows_v1 WHERE master_session_id=p_session ORDER BY preparation_revision DESC,id DESC LIMIT 1;
 pending:=EXISTS(SELECT 1 FROM public.mission_run_outbox WHERE master_session_id=p_session AND state IN('pending','human_directed'));
 active:=q.state='started' AND m.stato='in_corso' AND m.closed_at IS NULL AND r.run_phase='in_corso';
 reason:=CASE WHEN NOT mission_factory_owner.c444_enabled_v1() OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c407_control WHERE singleton AND admission_enabled AND manual_fato_enabled AND d100_enabled) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c412_control WHERE singleton AND runtime_enabled) THEN 'DISABLED' WHEN q.state='terminal' THEN 'TERMINAL' WHEN NOT active THEN 'NOT_ACTIVE' WHEN pending THEN 'FATO_PENDING' ELSE 'READY' END;
 ascope:=mission_factory_owner.c444_action_scope_v1(p_session);
 IF active THEN
  scene:=mission_factory_owner.quest_scene_v1(p_session,r.current_step_key);options:=coalesce(ascope->'decisions','[]'::jsonb);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(options)o WHERE (o->'to_step_key'='null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(scene->'terminal_options','[]'::jsonb))t WHERE t->>'decision_key'=o->>'decision_key' AND t->'to_step_key'='null'::jsonb)) OR (o->'to_step_key'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(scene->'triggers','[]'::jsonb))t WHERE t->>'decision_key'=o->>'decision_key'))) THEN RAISE EXCEPTION 'C456_NATIVE_COMPILED_DECISION_SOURCE_DRIFT' USING ERRCODE='40001';END IF;
  IF reason='READY' THEN scope:=public.mission_factory_quest_d100_binding_scope_v1(p_session);END IF;
 END IF;
 IF q.state='terminal' THEN term:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);SELECT * INTO ne FROM mission_factory_owner.quest_episodes WHERE arc_id=q.arc_id AND ordinal=q.episode_ordinal+1;IF ne.id IS NOT NULL THEN nextdto:=jsonb_build_object('quest_episode_id',ne.id,'ordinal',ne.ordinal,'source_sha256',ne.source_sha256,'eligible',mission_factory_owner.c444_enrollment_open_v1(ne.id),'reason_code',CASE WHEN NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true THEN 'DISABLED' WHEN mission_factory_owner.c444_enrollment_open_v1(ne.id) THEN 'READY' ELSE 'NATIVE_ENROLLMENT_CLOSED' END);END IF;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('receipt_id',rec.id,'binding_id',b.id,'source_sha256',rec.native_facts_sha256,'decision_key',rec.decision_key,'consumed',t.receipt_id IS NOT NULL) ORDER BY rec.created_at,rec.id),'[]'::jsonb) INTO ds FROM mission_factory_owner.c353_d100_bindings b JOIN mission_factory_owner.c353_d100_receipts rec ON rec.binding_id=b.id LEFT JOIN mission_factory_owner.c360_d100_transitions t ON t.receipt_id=rec.id WHERE b.session_id=p_session AND b.quest_source_sha256=q.source_sha256 AND b.step_key=r.current_step_key AND b.run_control_version=r.control_version;
 enc:=EXISTS(SELECT 1 FROM mission_creation_owner.human_encounters he JOIN public.combat_v2_sessions cs ON cs.id=he.encounter_id WHERE he.master_session_id=p_session AND he.step_key=r.current_step_key AND he.run_control_version=r.control_version AND cs.state='in_corso');
 IF reason='READY' AND enc AND EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_session_optins_v1 o WHERE o.master_session_id=p_session AND o.actor_user=auth.uid()) THEN ctx:=mission_generic_owner.regia_human_direction_context_v1(p_session);END IF;
 RETURN jsonb_build_object('schema_version','quest-human-runtime-state/1','native_session_id',p_session,'quest_episode_id',q.episode_id,'source_sha256',q.source_sha256,'phase',q.state,'current_step_key',r.current_step_key,'run_control_version',r.control_version,'master_control_version',m.control_version,'current_event',CASE WHEN ev.id IS NULL THEN NULL ELSE jsonb_build_object('event_id',ev.id,'operation_kind',ev.operation_kind,'status',ev.status,'version_after',ev.version_after,'result',ev.result) END,'scene',scene,'decisions',options,'action_scope',ascope,'next_episode',nextdto,'window',CASE WHEN hw.id IS NULL THEN NULL ELSE jsonb_build_object('window_id',hw.id,'state',hw.state,'side',hw.side,'preparation_revision',hw.preparation_revision,'source_round_id',hw.source_round_id,'source_report_id',hw.source_report_id,'next_round_id',hw.next_round_id,'publication_id',hw.publication_id,'request_key',hw.publication_request_key) END,'regia_context',ctx,'d100_scope',scope,'d100_receipts',ds,'terminal',term,'reward_policy',mission_factory_owner.quest_reward_fixed30_document_v2(),'can',jsonb_build_object('bind_d100',coalesce((scope->>'can_bind')::boolean,false),'consume_d100',reason='READY' AND EXISTS(SELECT 1 FROM jsonb_array_elements(ds)x WHERE x->>'consumed'='false'),'prepare_direction',reason='READY' AND coalesce((ctx->>'can_direct')::boolean,false)),'reason_code',reason);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c464_preview_overlay_v1(p_draft uuid, p_version bigint, p_basis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t mission_factory_owner.c464_transfer_sources;d mission_factory_owner.drafts;snapshot jsonb;media_refs jsonb:='[]';x mission_factory_owner.c464_media_transfers;receipt jsonb;
BEGIN
 SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_draft FOR SHARE;
 SELECT * INTO t FROM mission_factory_owner.c464_transfer_sources WHERE target_draft_id=p_draft AND target_version=p_version FOR SHARE;
 IF NOT FOUND THEN RETURN p_basis;END IF;
 IF auth.uid() IS DISTINCT FROM d.author_user THEN RAISE EXCEPTION 'C464_PREVIEW_OWN_AUTHOR_REQUIRED' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.c464_authoring_admit_v1();
 snapshot:=mission_factory_owner.c464_transfer_assert_v1(t.id,p_draft,p_version);
 FOR x IN SELECT * FROM mission_factory_owner.c464_media_transfers WHERE transfer_id=t.id ORDER BY target_episode_key,target_step_key NULLS FIRST LOOP
  receipt:=mission_factory_owner.c464_media_assert_v1(x.id,p_draft,p_version);
  media_refs:=media_refs||jsonb_build_array(jsonb_build_object('receipt_id',x.id,'receipt_sha256',x.receipt_sha256,
  'asset_sha256',receipt->>'sha256','episode_key',x.target_episode_key,'step_key',x.target_step_key));
 END LOOP;
 IF snapshot->'context_media' IS DISTINCT FROM 'null'::jsonb AND jsonb_array_length(media_refs)<>1
 THEN RAISE EXCEPTION 'C464_PREVIEW_CONTEXT_TRANSFER_REQUIRED';END IF;
 RETURN p_basis||jsonb_build_object('g2_binding',jsonb_build_object('transfer_id',t.id,'binding_sha256',t.source_sha256,
 'target_document_sha256',t.target_document_sha256,'media_transfers',media_refs));
 -- Private hashes enter the sealed preview basis, not public/provider DTOs. Existing ordinary basis stays byte-equivalent.
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c474_transfer_refresh_v1(p_draft uuid, p_version bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t mission_factory_owner.c464_transfer_sources;d mission_factory_owner.drafts;mapping jsonb;result jsonb;media jsonb;request uuid;
BEGIN
 SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_draft FOR UPDATE;
 SELECT * INTO t FROM mission_factory_owner.c464_transfer_sources WHERE target_draft_id=p_draft ORDER BY target_version DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF d.author_user IS DISTINCT FROM auth.uid() OR d.control_version IS DISTINCT FROM p_version
 OR d.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(d.document) THEN RAISE EXCEPTION 'C474_REFRESH_OWN_SOURCE_CAS';END IF;
 IF t.target_version=p_version THEN PERFORM mission_factory_owner.c464_transfer_assert_v1(t.id,p_draft,p_version);RETURN t.id;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('source_step_key',x->>'source_step_key','source_trigger_key',x->>'source_trigger_key',
 'decision_key',x->>'decision_key','target_step_key',x->>'target_step_key') ORDER BY ord),'[]'::jsonb) INTO mapping
 FROM jsonb_array_elements(t.source_snapshot->'trigger_map') WITH ORDINALITY m(x,ord);
 request:=extensions.uuid_generate_v5(p_draft,'g2-refresh:'||p_version::text||':'||d.document_sha256);
 result:=mission_factory_owner.c464_transfer_commit_v1(request,t.rapid_draft_id,t.rapid_version,p_draft,p_version,mapping);
 IF t.source_snapshot->'context_media' IS DISTINCT FROM 'null'::jsonb THEN
  media:=mission_factory_owner.c464_media_transfer_v1(extensions.uuid_generate_v5(request,'media'),(result->>'transfer_id')::uuid,
   t.source_snapshot->>'episode_key',t.source_snapshot#>>'{context_media,phase_key}');
 END IF;
 RETURN (result->>'transfer_id')::uuid;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_dual_import_v3(p_native_draft uuid, p_native_version bigint, p_human_variant jsonb, p_roster uuid[], p_lineage uuid, p_expected_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d mission_factory_owner.drafts;old mission_factory_owner.c422_import_sources;doc jsonb;fp text;result jsonb;r mission_factory_owner.quest_roster_assignments;
BEGIN
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'C422_NORMAL_AUTHOR_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(auth.uid());
IF p_request IS NULL OR p_native_draft IS NULL OR p_native_version IS NULL OR p_lineage IS NULL OR p_expected_version IS NULL THEN RAISE EXCEPTION 'C422_IMPORT_INPUT';END IF;
fp:=mission_factory_owner.sha(jsonb_build_object('native_draft',p_native_draft,'native_version',p_native_version,'human_variant',p_human_variant,'roster',p_roster,'lineage',p_lineage,'expected_version',p_expected_version,'actor_user',auth.uid()));
PERFORM pg_advisory_xact_lock(hashtextextended('c422-import:'||p_request::text,422));
SELECT * INTO old FROM mission_factory_owner.c422_import_sources WHERE request_key=p_request;
IF FOUND THEN
IF old.actor_user IS DISTINCT FROM auth.uid() OR old.fingerprint IS DISTINCT FROM fp OR old.native_document_sha256 IS DISTINCT FROM mission_factory_owner.sha(old.native_document) THEN RAISE EXCEPTION 'C422_IMPORT_REPLAY_CONFLICT';END IF;
RETURN old.result;
END IF;
SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_native_draft FOR SHARE;
IF d.author_user IS DISTINCT FROM auth.uid() OR d.control_version IS DISTINCT FROM p_native_version OR d.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(d.document) OR d.document->>'schema_version' IS DISTINCT FROM 'mission-factory-draft/2' OR d.document->>'content_kind' IS DISTINCT FROM 'quest_ai' THEN RAISE EXCEPTION 'C422_EXACT_NATIVE_DRAFT2_SOURCE_CAS_REQUIRED';END IF;
PERFORM mission_factory_owner.validate_quest_draft_v2(d.document);
IF d.document#>'{quest,roster_assignment_id}' IS DISTINCT FROM 'null'::jsonb THEN
SELECT * INTO STRICT r FROM mission_factory_owner.quest_roster_assignments WHERE id=(d.document#>>'{quest,roster_assignment_id}')::uuid AND draft_id=d.id AND active;
IF r.member_character_ids IS DISTINCT FROM p_roster THEN RAISE EXCEPTION 'C422_IMPORTED_ROSTER_MUST_MATCH_NATIVE';END IF;
END IF;
-- Only schema/mode and supplied typedHuman direction change. Nativeplot/PNG/maps/AIvariant remain exact.
doc:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(d.document,'{schema_version}','"mission-factory-draft/3"'::jsonb),'{content_kind}','"quest_dual"'::jsonb),'{variants,human}',p_human_variant),'{quest,roster_assignment_id}','null'::jsonb);
IF (doc-'schema_version'-'content_kind'-'variants'-'quest') IS DISTINCT FROM (d.document-'schema_version'-'content_kind'-'variants'-'quest') OR (doc->'quest'-'roster_assignment_id') IS DISTINCT FROM (d.document->'quest'-'roster_assignment_id') OR doc#>'{variants,ai}' IS DISTINCT FROM d.document#>'{variants,ai}' THEN RAISE EXCEPTION 'C422_COMMON_SOURCE_CHANGED';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(doc);
result:=public.mission_factory_quest_dual_create_v3(p_lineage,p_expected_version,doc,p_roster,p_request);
PERFORM mission_factory_owner.c474_import_fork_v1(p_native_draft,p_native_version,(result->>'draft_id')::uuid,(result->>'version')::bigint,p_request);
INSERT INTO mission_factory_owner.c422_import_sources(request_key,native_draft_id,native_draft_version,native_document_sha256,native_document,actor_user,fingerprint,result)VALUES(p_request,d.id,d.control_version,d.document_sha256,d.document,auth.uid(),fp,result);
RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_editor_ready_v1(p_client_build text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r mission_factory_owner.editor_release_readiness; role_name text;
        permitted boolean;
begin
  if auth.uid() is null then raise exception 'MF_READY_AUTH_REQUIRED' using errcode='42501'; end if;
  select p.role into role_name from public.profiles p where p.id=auth.uid();
  if coalesce(role_name,'') not in('admin','master') then
    raise exception 'MF_READY_STAFF_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_client_build,'') !~ '^mission-factory-admin/2:[0-9a-f]{64}$' then
    return jsonb_build_object('schema_version','mission-factory-editor-ready/1',
      'state','prepared','scope','staff','client_build',null,'revision_sha256',null);
  end if;
  select * into r from mission_factory_owner.editor_release_readiness where singleton;
  permitted:=r.singleton is not null and r.scope='staff'
    and r.client_build=p_client_build
    and r.revision_sha256=pg_catalog.encode(extensions.digest(
      pg_catalog.convert_to(r.canonical_preimage,'UTF8'),'sha256'),'hex')
    and (r.state<>'enabled' or (
      r.observed_revision_sha256=r.revision_sha256
      and r.staff_guards_verified and r.published_assets_verified
      and length(btrim(coalesce(r.independent_review_ref,'')))>0));
  if not coalesce(permitted,false) then
    return jsonb_build_object('schema_version','mission-factory-editor-ready/1',
      'state','prepared','scope','staff','client_build',null,'revision_sha256',null);
  end if;
  return jsonb_build_object('schema_version','mission-factory-editor-ready/1',
    'state',r.state,'scope','staff','client_build',r.client_build,
    'revision_sha256',r.revision_sha256);
end $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_run_state_v1(p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q mission_factory_owner.quest_run_sources%rowtype;
  m public.master_v2_sessions%rowtype;
  r public.mission_run_state%rowtype;
  e public.mission_run_events%rowtype;
  ob public.mission_run_outbox%rowtype;
  c mission_ai_service_owner.capabilities%rowtype;
  op text; st text; receipt jsonb; n integer;
  terminal_event public.mission_run_events%rowtype;
begin
IF EXISTS(SELECT 1 FROM mission_factory_owner.c384_human_bindings b JOIN mission_factory_owner.quest_run_sources q ON q.session_id=b.session_id WHERE q.prepare_request_key=p_request OR q.start_request_key=p_request OR EXISTS(SELECT 1 FROM public.mission_run_events ev WHERE ev.master_session_id=q.session_id AND ev.operation_kind='close' AND ev.request_key_sha256=mission_internal.request_key_sha256(p_request))) THEN RETURN mission_factory_owner.c444_run_state_v1(p_request);END IF;

  perform mission_ai_board_owner.staff_only();
  if p_request is null then
    raise exception 'MF_QUEST_READBACK_REQUEST' using errcode='22023'; end if;
  select count(*) into n from (
    select run_source.session_id from mission_factory_owner.quest_run_sources run_source
      where run_source.prepare_request_key=p_request or run_source.start_request_key=p_request
    union all
    select ev.master_session_id from public.mission_run_events ev
      join mission_factory_owner.quest_run_sources run_source on run_source.session_id=ev.master_session_id
      where ev.operation_kind='close'
        and ev.request_key_sha256=mission_internal.request_key_sha256(p_request)
  ) requests;
  if n=0 then
    return jsonb_build_object('schema_version','quest-episode-run-state/1',
      'request_key',p_request,'operation',null,'state','unknown','receipt',null,
      'run_control_version',null,'opening_publication_id',null);
  elsif n<>1 then
    raise exception 'MF_QUEST_READBACK_AMBIGUOUS' using errcode='40001'; end if;
  select * into terminal_event from public.mission_run_events ev
    where ev.operation_kind='close'
      and ev.request_key_sha256=mission_internal.request_key_sha256(p_request)
      and exists(select 1 from mission_factory_owner.quest_run_sources run_source
        where run_source.session_id=ev.master_session_id) for share;
  if terminal_event.id is not null then
    select * into strict q from mission_factory_owner.quest_run_sources
      where session_id=terminal_event.master_session_id for share;
    op:='terminal';
  else
    select * into strict q from mission_factory_owner.quest_run_sources
      where prepare_request_key=p_request or start_request_key=p_request for share;
    op:=case when p_request=q.prepare_request_key then 'prepare' else 'start' end;
  end if;
  select * into strict m from public.master_v2_sessions
    where id=q.session_id for share;
  select * into strict r from public.mission_run_state
    where master_session_id=q.session_id for share;
  if op<>'terminal' and m.stato='chiusura' then
    select * into terminal_event from public.mission_run_events
      where id=r.last_event_id and master_session_id=q.session_id
        and operation_kind='close' for share;
  end if;
  st:=q.state;
  if op='prepare' then
    receipt:=jsonb_build_object('schema_version','quest-episode-prepare/1',
      'request_key',p_request,'state','prepared',
      'quest_arc_id',q.arc_id,'quest_episode_id',q.episode_id,
      'native_session_id',q.session_id,'source_sha256',q.source_sha256,
      'plan_version_id',q.plan_version_id,'plan_sha256',q.plan_sha256,
      'roster_snapshot_sha256',q.roster_snapshot_sha256,
      'staff_release_sha256',q.staff_release_sha256,
      'location_id',q.location_id,'control_version',1,
      'opening_publication_id',null);
  elsif op='start' then
    select * into e from public.mission_run_events
      where id=q.start_event_id and master_session_id=q.session_id for share;
    if e.id is null or e.operation_kind<>'bind' or e.status<>'committed'
       or e.request_key_sha256<>mission_internal.request_key_sha256(p_request)
       or e.plan_version_id is distinct from q.plan_version_id
       or e.version_after is distinct from 1
       or e.result->>'schema_version' is distinct from 'quest-episode-start/1'
    then st:='uncertain'; receipt:=null;
    else
      receipt:=e.result;
      select * into ob from public.mission_run_outbox
        where event_id=e.id and master_session_id=q.session_id for share;
      select * into c from mission_ai_service_owner.capabilities
        where master_session_id=q.session_id for share;
      if ob.event_id is null or c.id is null
         or c.quest_source_session_id is distinct from q.session_id
         or c.start_request_key is distinct from q.start_request_key
      then st:='uncertain'; end if;
    end if;
  else
    receipt:=null;
  end if;
  if q.state='prepared' then
    if m.stato<>'preparazione' or m.control_version<>1
       or r.run_phase<>'preparazione' or r.control_version<>1
       or r.last_event_id is not null or q.start_event_id is not null
    then st:='uncertain'; end if;
  elsif q.state='started' then
    if st<>'uncertain' and m.stato='chiusura'
       and r.last_event_id is not distinct from terminal_event.id
       and terminal_event.id is not null and terminal_event.operation_kind='close'
       and terminal_event.status='committed'
       and terminal_event.result->>'schema_version'='quest-native-close/1'
       and terminal_event.version_after=r.control_version
       and terminal_event.plan_version_id=q.plan_version_id
       and q.opening_publication_id is not null
       and exists(select 1 from public.mission_run_publications opening
         where opening.id=q.opening_publication_id
           and opening.event_id=q.start_event_id
           and opening.master_session_id=q.session_id
           and opening.status='committed')
       and (op<>'terminal' or terminal_event.request_key_sha256=
         mission_internal.request_key_sha256(p_request))
       and exists(select 1 from public.mission_run_outbox pending
         where pending.event_id=terminal_event.id
           and pending.master_session_id=q.session_id and pending.state='pending')
    then
      st:='closing_pending'; receipt:=null;
    elsif op='terminal' then
      st:='uncertain'; receipt:=null;
    else
    if op='prepare' and ob.event_id is null then
      select * into ob from public.mission_run_outbox
        where event_id=q.start_event_id and master_session_id=q.session_id for share;
      select * into c from mission_ai_service_owner.capabilities
        where master_session_id=q.session_id for share;
    end if;
    if ob.event_id is null or c.id is null
       or ob.state is distinct from 'published'
       or ob.publication_id is distinct from q.opening_publication_id
       or not exists(select 1 from public.mission_run_publications p
         where p.id=q.opening_publication_id and p.event_id=q.start_event_id
           and p.master_session_id=q.session_id and p.status='committed')
       or not exists(select 1 from public.mission_run_messages msg
         where msg.publication_id=q.opening_publication_id)
       or m.stato<>'in_corso' or m.closed_at is not null or m.control_version<2
       or r.run_phase<>'in_corso' or r.plan_version_id is distinct from q.plan_version_id
       or r.control_version<1 or r.last_event_id is null
       or c.state is distinct from 'active' or c.expected_control_version<2
       or c.expected_control_version>m.control_version
       or c.quest_source_session_id is distinct from q.session_id
    then st:='uncertain'; else st:='started'; end if;
    end if;
  elsif q.state='terminal' then
    receipt:=mission_factory_owner.quest_terminal_confirmed_v1(q.session_id);
    if receipt is not null and
       (op<>'terminal' or
        (terminal_event.id is not null and
         receipt->>'request_key'=p_request::text))
    then st:='terminal'; else st:='uncertain'; receipt:=null; end if;
  end if;
  return jsonb_build_object('schema_version','quest-episode-run-state/1',
    'request_key',p_request,'operation',op,'state',st,'receipt',receipt,
    'run_control_version',r.control_version,
    'opening_publication_id',case when st in ('started','closing_pending','terminal')
      then q.opening_publication_id else null end);
end; $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_enrollment_v1(p_episode uuid, p_operation text, p_ready boolean, p_expected_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); c public.characters%rowtype;
  e mission_factory_owner.quest_episodes%rowtype;
  a mission_factory_owner.quest_arcs%rowtype;
  pub mission_factory_owner.publications%rowtype;
  x mission_factory_owner.quest_episode_enrollments%rowtype;
  old mission_factory_owner.quest_episode_enrollment_requests%rowtype;
  fp text; receipt jsonb;
begin
IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes e JOIN mission_factory_owner.quest_arcs a ON a.id=e.arc_id JOIN mission_factory_owner.publications p ON p.request_key=a.publication_request WHERE e.id=p_episode AND p.content_kind='quest_human') THEN RETURN mission_factory_owner.c444_enrollment_v1(p_episode,p_operation,p_ready,p_expected_version,p_request);END IF;

  if uid is null or p_episode is null or p_request is null
     or p_operation is null or p_operation not in ('join','withdraw','ready')
     or (p_operation='ready' and p_ready is null)
     or (p_operation<>'ready' and p_ready is not null)
     or (p_operation='join' and p_expected_version is not null)
     or (p_operation in ('withdraw','ready') and
         (p_expected_version is null or p_expected_version<1))
  then raise exception 'MF_QUEST_ENROLLMENT_INPUT' using errcode='22023'; end if;
  select * into strict c from public.characters where user_id=uid;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,25092601));
  fp:=mission_factory_owner.sha(jsonb_build_object('episode',p_episode,
    'operation',p_operation,'character',c.id,'ready',p_ready,
    'expected_version',p_expected_version));
  select * into old from mission_factory_owner.quest_episode_enrollment_requests
    where request_key=p_request for share;
  if found then
    if old.actor_user<>uid or old.episode_id<>p_episode
       or old.character_id<>c.id or old.operation<>p_operation
       or old.request_fingerprint<>fp
    then raise exception 'MF_QUEST_ENROLLMENT_REQUEST_CONFLICT' using errcode='23505'; end if;
    return old.result;
  end if;
  select * into strict a from mission_factory_owner.quest_arcs
    where id=(select arc_id from mission_factory_owner.quest_episodes where id=p_episode) for share;
  select * into strict e from mission_factory_owner.quest_episodes
    where id=p_episode and arc_id=a.id for update;
  select * into strict pub from mission_factory_owner.publications
    where request_key=a.publication_request for share;
  if not mission_factory_owner.quest_episode_enrollment_open_v1(e.id)
     or pub.content_kind<>'quest_ai' or not mission_factory_owner.quest_public_open_v3(a.id)
     or pub.quest_arc_id<>a.id
     or e.source_sha256<>mission_factory_owner.sha(e.source_document)
     or not(c.id=any(e.member_character_ids)) or c.user_id is distinct from uid
     or exists(select 1 from mission_factory_owner.quest_run_sources
       where episode_id=p_episode)
  then raise exception 'MF_QUEST_ENROLLMENT_CLOSED' using errcode='55000'; end if;
  perform pg_advisory_xact_lock(hashtextextended(c.id::text,203));
  select * into x from mission_factory_owner.quest_episode_enrollments
    where episode_id=p_episode and character_id=c.id for update;
  if p_operation='join' then
    if x.character_id is null or x.state='withdrawn' then
      if exists(select 1 from public.mission_bookings b
          join public.missions m on m.id=b.mission_id
          where b.character_id=c.id and b.status='iscritto'
            and m.status in ('aperta','programmata'))
         or exists(select 1 from public.master_v2_participants mp
           join public.master_v2_sessions ms on ms.id=mp.session_id
           where mp.character_id=c.id and mp.left_at is null and ms.closed_at is null)
         or exists(select 1 from mission_ai_board_owner.roster_reservations rr
           where rr.character_id=c.id and rr.state='active')
      then raise exception 'MF_QUEST_CHARACTER_BUSY' using errcode='40001'; end if;
    end if;
    if x.character_id is null then
      insert into mission_factory_owner.quest_episode_enrollments(
        episode_id,character_id,user_id_snapshot,source_sha256,
        roster_assignment_id,state)
      values(p_episode,c.id,uid,e.source_sha256,e.roster_assignment_id,'joined')
      returning * into x;
    elsif x.user_id_snapshot<>uid or x.source_sha256<>e.source_sha256
       or x.roster_assignment_id<>e.roster_assignment_id
    then raise exception 'MF_QUEST_ENROLLMENT_SOURCE_DRIFT' using errcode='40001';
    elsif x.state='withdrawn' then
      update mission_factory_owner.quest_episode_enrollments
        set state='joined',ready=false,ready_at=null,
          control_version=control_version+1,joined_at=clock_timestamp(),
          changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    end if;
  else
    if x.character_id is null or x.user_id_snapshot<>uid or x.state<>'joined'
    then raise exception 'MF_QUEST_NOT_JOINED' using errcode='55000'; end if;
    if x.control_version<>p_expected_version
    then raise exception 'MF_QUEST_ENROLLMENT_CAS' using errcode='40001'; end if;
    if p_operation='withdraw' then
      update mission_factory_owner.quest_episode_enrollments
        set state='withdrawn',ready=false,ready_at=null,
          control_version=control_version+1,changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    else
      update mission_factory_owner.quest_episode_enrollments
        set ready=p_ready,ready_at=case when p_ready then clock_timestamp() else null end,
          control_version=control_version+1,changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    end if;
  end if;
  receipt:=jsonb_build_object('schema_version','quest-episode-enrollment/1',
    'request_key',p_request,'quest_episode_id',p_episode,'character_id',c.id,
    'source_sha256',x.source_sha256,'roster_assignment_id',x.roster_assignment_id,
    'state',x.state,'ready',x.ready,'control_version',x.control_version);
  insert into mission_factory_owner.quest_episode_enrollment_requests(
    request_key,episode_id,character_id,actor_user,operation,request_fingerprint,result)
  values(p_request,p_episode,c.id,uid,p_operation,fp,receipt);
  return receipt;
end; $function$
